    json_extract_string(fileinfo, '$.url') as image_url,
    cast(credit as varchar) as credit,
    json_extract_string(constraintsinfo, '$.constraint') as licence,
    cast(permalinkurl as varchar) as link,
    json_merge_patch(
        to_json(base_nps__nps_gallery_assets),
        '{"description": null, "transcript": null, '
        || '"shortdescription": null, "longdescription": null, '
        || '"accessibilityinformation": null, "feedescription": null, '
        || '"reservationdescription": null, '
        || '"seasondescription": null, "petsdescription": null, '
        || '"locationdescription": null, "activitydescription": null, '
        || '"agedescription": null, "timeofdaydescription": null, '
        || '"durationdescription": null, "alttext": null, '
        || '"images": null, "stops": null}'
    ) as properties,
    _loaded_at
from {{ ref('base_nps__nps_gallery_assets') }}
